#!/usr/bin/env python3
"""Render reference data into fixed files without changing consumer policies."""

import argparse
import importlib.util
import json
from pathlib import Path
from pprint import pformat
import sys

ROOT = Path(__file__).resolve().parents[1]
GROUPS = (
    "receipt_types", "request_extra_types", "decisions", "policy_decisions",
    "capture_topologies", "sandbox_states", "witnesses", "standard_risk_classes",
    "dora_incident_classes", "hipaa_incident_classes",
)
ALIASES = {
    "PolicyDecision": "POLICY_DECISIONS",
    "Decision": "DECISIONS",
    "CaptureTopology": "CAPTURE_TOPOLOGIES",
}
OUTPUTS = ("wire.py", "wire.ts", "wire-cases.json")


def _validator():
    spec = importlib.util.spec_from_file_location("wire_reference", ROOT / "vocabulary/validate.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load_reference(directory: Path) -> dict:
    """Load wire.json from a directory through the required reference validator."""
    validator = _validator()
    document = validator.load(Path(directory) / "wire.json")
    validator.validate(document)
    return document


def _values(document: dict) -> dict:
    _validator().validate(document)
    for name, field in document["fields"].items():
        if field["list_entry_max_length"] > 2**53 - 1:
            raise ValueError(f"fields.{name}.list_entry_max_length exceeds exact TypeScript integers")
    values = {name.upper(): document[name] for name in GROUPS}
    for profile, groups in document["profiles"].items():
        values[profile.upper()] = [item for group in groups for item in document[group]]
    values.update(
        DECISION_MAP=dict(document["decision_map"]),
        METADATA_ORDER=document["metadata_order"], METADATA=document["metadata"],
        TAXONOMY_ORDER=document["taxonomy_order"],
        FIELDS={name: document["fields"][name] for name in document["taxonomy_order"]},
    )
    return values


def render_python(document: dict) -> bytes:
    """Return literal data and typing aliases; consumer validation stays handwritten."""
    values = _values(document)
    lines = ['"""Generated by tools/wire_vocabulary.py; edit vocabulary/wire.json."""',
             "from typing import Literal", ""]
    for name, value in values.items():
        literal = tuple(value) if isinstance(value, list) else value
        lines.append(f"{name} = {pformat(literal, sort_dicts=False, width=88)}\n")
    for alias, name in ALIASES.items():
        members = ", ".join(repr(value) for value in values[name])
        lines.append(f"{alias} = Literal[{members}]")
    return ("\n".join(lines) + "\n").encode("utf-8")


def render_typescript(document: dict) -> bytes:
    """Return const data and indexed aliases with literal TypeScript inference."""
    lines = ["// Generated by tools/wire_vocabulary.py; edit vocabulary/wire.json"]
    for name, value in _values(document).items():
        literal = json.dumps(value, ensure_ascii=True, allow_nan=False, indent=2)
        lines.append(f"export const {name} = {literal} as const;\n")
    for alias, name in ALIASES.items():
        lines.append(f"export type {alias} = (typeof {name})[number];")
    return ("\n".join(lines) + "\n").encode("utf-8")


def render_cases(document: dict) -> bytes:
    """Return lexical membership cases, with no receipt or cryptographic verdict."""
    values = _values(document)
    cases = [{"value": value, "receipt_profile": value in values["RECEIPT_PROFILE"],
              "receipt_request": True} for value in values["RECEIPT_REQUEST"]]
    result = {"kind": "lexical-vocabulary", "values": values, "type_membership": cases}
    return (json.dumps(result, ensure_ascii=True, allow_nan=False, indent=2) + "\n").encode("utf-8")


def _paths(root: Path) -> list[Path]:
    paths = [root / "vocabulary/generated" / name for name in OUTPUTS]
    for path in paths:
        for part in (path, *path.parents):
            if part.is_symlink():
                raise ValueError(f"symlink output path: {part}")
        if path.exists() and not path.is_file():
            raise ValueError(f"output is not a file: {path}")
        for parent in path.parents:
            if parent.exists() and not parent.is_dir():
                raise ValueError(f"output parent is not a directory: {parent}")
    return paths


def _sync(root: Path, write: bool) -> list[str]:
    paths = _paths(root)
    document = load_reference(root / "vocabulary")
    contents = (render_python(document), render_typescript(document), render_cases(document))
    drift = []
    for path, content in zip(paths, contents, strict=True):
        if write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)
        elif not path.exists() or path.read_bytes() != content:
            drift.append(str(path.relative_to(root)))
    return drift


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--write", action="store_true")
    args = parser.parse_args(argv)
    try:
        drift = _sync(ROOT, args.write)
        if drift:
            raise ValueError("generated output drift: " + ", ".join(drift))
    except (OSError, UnicodeError, ValueError) as exc:
        print(f"FAIL: {exc}", file=sys.stderr)
        return 1
    print("OK: generated wire vocabulary files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
